function csvRows(src){const rows=[],row=[];let cell='',quoted=false;src=src.replace(/^\uFEFF/,'');for(let i=0;i<src.length;i++){const c=src[i];if(c==='"'){if(quoted&&src[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&src[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push([...row]);row.length=0;cell=''}else cell+=c}if(quoted)throw Error('Unclosed CSV quotation');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows}
const csvQ=x=>'"'+String(x??'').replace(/"/g,'""')+'"';
function exportIssuesCSV(){const cols=['ID','Location','Description','Discipline','Date','Status','ClosedDate','DrawingID','PinX','PinY','PhotoCount','Priority','Responsible','DueDate','Trade','RootCause','CorrectiveAction','VerifiedBy','VerifiedDate','Tags','Checklist'];const rows=S.snags.map(s=>[s.id,s.location,s.desc,s.disc,s.date,s.status,s.closedDate||'',s.drawingId||'',s.x??'',s.y??'',(s.photos||[]).length,s.priority||'',s.assignee||'',s.dueDate||'',s.trade||'',s.rootCause||'',s.correctiveAction||'',s.verifiedBy||'',s.verifiedDate||'',s.tags||'',(s.checklist||[]).map(c=>c.name+': '+c.result).join('; ')]);const blob=new Blob(['\uFEFF'+[cols,...rows].map(r=>r.map(csvQ).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='GEM_Issues_'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importIssuesRows(rows,fileName){
 if(rows.length<2)throw Error('File requires a header and data rows');
 const headers=rows.shift().map(s=>String(s??'').trim().toLowerCase());
 const get=(r,...names)=>{const i=headers.findIndex(h=>names.includes(h));return i<0?'':String(r[i]??'').trim()};
 if(!headers.includes('description')&&!headers.includes('الوصف'))throw Error('Missing Description column');
 const add=[],skip=[],ids=new Set(S.snags.map(s=>s.id));
 for(let i=0;i<rows.length;i++){
  const r=rows[i],desc=get(r,'description','الوصف'),loc=get(r,'location','الموقع')||S.locations[0],disc=get(r,'discipline','التخصص')||'Architectural',status=get(r,'status','الحالة')||'Open',date=get(r,'date','logged','تاريخ التسجيل')||today(),given=get(r,'id');
  if(!desc||!DISC[disc]||!STAT.includes(status)||!/^(19|20)\d{2}-\d{2}-\d{2}$/.test(date)||(given&&ids.has(given))){skip.push(i+2);continue}
  if(given)ids.add(given);
  add.push({id:given,desc,location:loc,disc,status,date,closedDate:status==='Closed'?(get(r,'closeddate')||today()):'',photos:[],drawingId:null,x:null,y:null,history:[]});
 }
 if(!add.length)throw Error('No valid new records. Check disciplines/status/duplicate IDs');
 if(!confirm(`Import ${add.length} issues? ${skip.length} invalid or duplicate rows will be skipped. Existing issues will not be overwritten.`))return;
 for(const x of add){if(!S.locations.includes(x.location))S.locations.push(x.location);x.seq=++S.n;if(!x.id)x.id=snagId(x.disc);logChange(x,'Imported from '+fileName);S.snags.push(x)}
 await flushSave();render();toast(`Imported ${add.length} issues; skipped ${skip.length}`);
}
async function importIssuesCSV(file){try{await importIssuesRows(csvRows(await file.text()),file.name)}catch(e){toast('CSV import failed: '+e.message)}}
async function importIssuesXLSX(file){toast('XLSX import is not available in this offline edition. Use CSV import. / يرجى استخدام CSV للاستيراد')}
async function exportIssuesXLSX(){try{await flushSave();GEM_EXPORT_XLSX(S)}catch(e){toast('XLSX export failed: '+e.message)}}
