function openUnifiedSearch(){
 let panel=document.getElementById('gem-search-panel');if(!panel){panel=document.createElement('div');panel.id='gem-search-panel';panel.className='gem-search-panel';document.body.appendChild(panel)}panel.hidden=false;
 panel.innerHTML='<div class="gem-search-card"><div class="row"><h3>Search project / البحث في المشروع</h3><span style="flex:1"></span><button id="search-close" class="btn">✕</button></div><input id="global-query" placeholder="Issue ID, location, drawing, activity… / ابحث هنا" aria-label="Search entire project"><div id="global-results" class="global-results"></div></div>';
 panel.querySelector('#search-close').onclick=()=>{panel.hidden=true};panel.onclick=e=>{if(e.target===panel)panel.hidden=true};const input=panel.querySelector('#global-query');
 const build=()=>{const q=input.value.trim().toLowerCase();const out=[];if(q.length<2){panel.querySelector('#global-results').innerHTML='<p class="muted">Enter at least 2 characters / أدخل حرفين على الأقل</p>';return}
 for(const s of S.snags||[])if([s.id,s.desc,s.location,s.assignee,s.trade,s.tags].some(v=>String(v||'').toLowerCase().includes(q)))out.push({kind:'Issue',label:s.id+' · '+s.desc,action:()=>issueDlg(s)});
 for(const d of S.drawings||[])if([d.name,d.revision].some(v=>String(v||'').toLowerCase().includes(q)))out.push({kind:'Drawing',label:d.name,action:()=>{selDraw=d.id;view='draw';render()}});
 for(const r of sched?.rows||[])if(r.type==='Task'&&[r.no,r.en].some(v=>String(v||'').toLowerCase().includes(q)))out.push({kind:'Schedule',label:r.no+' · '+r.en,action:()=>{view='plan';planningPanel='schedule';render()}});
 const res=panel.querySelector('#global-results');res.innerHTML=out.slice(0,60).map((a,i)=>`<button class="global-result" data-result="${i}"><b>${a.kind}</b> ${esc(a.label)}</button>`).join('')||'<p class="muted">No results / لا توجد نتائج</p>';res.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{panel.hidden=true;out[+b.dataset.result].action()})};input.oninput=build;build();input.focus()
}
function systemHealthReport(){const ids=new Set(),duplicate=[],missingPhoto=[],missingDrawing=[],badPins=[];for(const s of S.snags||[]){if(ids.has(s.id))duplicate.push(s.id);ids.add(s.id);if((s.photos||[]).some(p=>!p.url))missingPhoto.push(s.id);if(s.drawingId&&!S.drawings.some(d=>d.id===s.drawingId))missingDrawing.push(s.id);if(s.x!=null&&(!Number.isFinite(+s.x)||!Number.isFinite(+s.y)||+s.x<0||+s.y<0||+s.x>100||+s.y>100))badPins.push(s.id)}const issues=[['Duplicate IDs',duplicate],['Missing drawing refs',missingDrawing],['Invalid pin coordinates',badPins],['Missing image references',missingPhoto]];const m=$('#modal2');m.hidden=false;m.dataset.keep='1';m.innerHTML=`<div class="dlg"><h3>Project Health / فحص سلامة المشروع <button class="btn" id="health-close">✕</button></h3><div class="pad"><p>Project records: <b>${S.snags.length} issues</b> · <b>${S.drawings.length} drawings</b></p>${issues.map(([k,v])=>`<p><b>${esc(k)}:</b> ${v.length} ${v.length?'<small>'+esc(v.slice(0,8).join(', '))+'</small>':'✓'}</p>`).join('')}<p class="muted">This checks local state structure only. It does not replace file integrity or Windows acceptance tests.</p><button id="health-download" class="btn">Export JSON</button></div></div>`;$('#health-close').onclick=()=>{m.hidden=true;m.dataset.keep='0';m.innerHTML=''};$('#health-download').onclick=()=>{const blob=new Blob([JSON.stringify({date:new Date().toISOString(),issueCount:S.snags.length,drawingCount:S.drawings.length,findings:Object.fromEntries(issues)},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='GEM_Project_Health.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
}
function wireGlobalTools(){const nav=document.querySelector('.nav');if(!nav)return;const slot=document.createElement('div');slot.className='classic-global-tools';slot.innerHTML='<button class="btn" id="global-search-button" title="Ctrl+K">⌕ Search / بحث</button><button class="btn" id="global-health-button">✓ Health</button>';nav.appendChild(slot);slot.querySelector('#global-search-button').onclick=openUnifiedSearch;slot.querySelector('#global-health-button').onclick=systemHealthReport}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openUnifiedSearch()} });

const NAV=[['dash','Dashboard','dash','#2b7bd6'],['draw','Drawings & Location','map','#c0873a'],['snags','Snags','snag','#d64545'],['plan','Planning','plan','#1f9d63'],['rep','Reports','rep','#8e44ad'],['set','Settings','set','#5a6b80']];
function render(){const m=view;hidePop();$('#app').innerHTML=`<div class="head"><img src="${esc(S.settings.logoL||'assets/logo_gem.png')}" alt="Grand Egyptian Museum"><h1>${esc(S.settings.company||'GEM Construction Management')}<small>${S.settings.demo?'DEMO · TEST DATA ONLY':'Snagging &amp; Site Observations'}</small></h1><img src="${esc(S.settings.logoR||'assets/logo_hill.png')}" alt="Hill International / EHAF"></div>
<div class="nav">${NAV.map(n=>`<button class="${m===n[0]?'on':''}" data-v="${n[0]}"><span class="ico" style="--c:${n[3]}">${ic(n[2])}</span>${n[1]}</button>`).join('')}</div><div id="save-state" class="save-state">✓ Saved</div><main class="${m==='draw'?'full':''}">${({dash,draw,snags,plan,rep,set})[m]()}</main>`;
 document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{view=b.dataset.v;if(view==='snags')classicIssueSubset='all';pickCtx=null;pinMode=false;render()});wire();if(m==='dash')wireClassicDashboard();if(m==='draw')wireLayout();simplifyClassicWorkspace();wireGlobalTools()}
const pill=s=>`<span class="tag" style="background:${col(s)}">${s}</span>`;

function dash(){
 const issues=S.snags||[],total=issues.length,closed=issues.filter(x=>x.status==='Closed').length,active=issues.filter(x=>x.status!=='Closed'),old=active.filter(x=>age(x)>=AGEDAYS()),unpinned=issues.filter(x=>!x.drawingId||x.x==null||x.y==null);
 const counts=Object.fromEntries(STAT.map(k=>[k,issues.filter(x=>x.status===k).length]));
 const kpi=(name,val,color,filter,tip)=>`<button type="button" class="card stat classic-kpi" style="--c:${color}" data-dashfilter="${esc(filter)}" title="${esc(tip)}"><b>${val}</b><span>${esc(name)}</span><small>Open filtered issues ›</small></button>`;
 let percent=total?Math.round(100*closed/total):0;
 let taskCount=sched&&sched.rows?sched.rows.filter(x=>x.type==='Task').length:0;
 let updated=taskCount&&S.prog?Object.keys(S.prog).filter(id=>S.prog[id]!==null&&S.prog[id]!==''&&S.prog[id]!==undefined).length:0;
 const latest=[...issues].sort((a,b)=>String(b.history?.at||b.date||'').localeCompare(String(a.history?.at||a.date||''))).slice(0,7);
 const recent=issues.flatMap(x=>(x.history||[]).slice(-3).map(h=>({...h,id:x.id,desc:x.desc}))).sort((a,b)=>String(b.at||'').localeCompare(String(a.at||''))).slice(0,5);
 return `<div class="bar"><h2>Dashboard</h2><span class="muted">Project overview · ${esc(today())}</span><button class="btn pri" data-a="new">${ic('plus')}New Issue</button><button class="btn" data-a="print">${ic('print')}Print</button></div>
 <div class="stats classic-stats">${kpi('Total snags',total,'#14263d','all','All observations')}${STAT.map(s=>kpi(s,counts[s],col(s),s,'Observations with '+s+' status')).join('')}</div>
 <div class="classic-summary">
  <div class="card pad classic-progress"><div class="classic-title"><b>Issue closure</b><span>${closed} / ${total} closed</span></div><div class="classic-meter"><i style="width:${percent}%"></i></div><div class="classic-foot"><b>${percent}%</b><span>Issue closure rate, not construction progress</span></div></div>
  <div class="card pad classic-progress"><div class="classic-title"><b>Planning data coverage</b><span>${updated} / ${taskCount} activities updated</span></div><div class="classic-meter"><i style="width:${taskCount?Math.round(updated*100/taskCount):0}%;background:#2b7bd6"></i></div><div class="classic-foot"><b>${taskCount?Math.round(updated*100/taskCount):0}%</b><span>Updates recorded · not actual progress</span></div></div>
  <button type="button" class="card pad classic-warning" data-dashfilter="aged"><b>${old.length}</b><span>Aged open issues</span><small>${AGEDAYS()}+ days · open list ›</small></button>
  <button type="button" class="card pad classic-warning" data-dashfilter="unpinned"><b>${unpinned.length}</b><span>Issues without pins</span><small>Review locations ›</small></button>
 </div>
 <div class="card pad" style="margin:10px 0;display:flex;justify-content:space-between;align-items:center;gap:12px"><span><b>Schedule activity checks / مراجعة حالات الأنشطة</b><br><small class="muted">Incomplete or contradictory status versus recorded progress</small></span><button type="button" class="btn ${scheduleInconsistencies().length?'work-alert':''}" id="dash-work-check">${scheduleInconsistencies().length} need review · Open schedule</button></div>
 <div class="classic-triage">
 <button class="card pad classic-warning" data-dashfilter="critical"><b>${issues.filter(x=>x.status!=='Closed'&&x.priority==='Critical').length}</b><span>Critical open issues</span><small>Open urgent observations ›</small></button>
 <button class="card pad classic-warning" data-dashfilter="due-soon"><b>${issues.filter(x=>x.status!=='Closed'&&x.dueDate&&x.dueDate>=today()&&x.dueDate<=new Date(Date.now()+7*86400000).toISOString().slice(0,10)).length}</b><span>Due within 7 days</span><small>Review upcoming deadlines ›</small></button>
 <button class="card pad classic-warning" data-dashfilter="pending-verification"><b>${issues.filter(x=>x.status!=='Closed'&&(x.visits||[]).some(v=>v.result==='Rectified')&&!x.verifiedBy).length}</b><span>Pending verification</span><small>Rectified but not signed off ›</small></button>
 </div>
 <div class="classic-section-label"><b>Operations &amp; Quality / العمليات والجودة</b><span>Linked to recorded project data only</span></div><div class="grid2 classic-panels">
  <div class="card pad"><div class="classic-title"><b>By discipline</b><button class="btn classic-link" data-dashview="snags">Open snag log ›</button></div>${Object.keys(DISC).map(d=>{const n=issues.filter(x=>x.disc===d).length;return `<button type="button" class="row classic-disc" data-dashdisc="${esc(d)}"><span style="width:112px">${esc(d)}</span><div class="bg"><i style="width:${total?100*n/total:0}%;--c:${DISC[d][1]}"></i></div><b>${n}</b></button>`}).join('')}</div>
  <div class="card pad"><div class="classic-title"><b>Latest observations</b><button class="btn classic-link" data-dashview="snags">View all ›</button></div><div class="classic-tablewrap"><table><thead><tr><th>ID</th><th>Location</th><th>Description</th><th>Status</th></tr></thead><tbody>${latest.map(x=>`<tr class="classic-observation" data-dashissue="${esc(x.id)}" title="Open this observation"><td>${esc(x.id)}</td><td>${esc(x.location||'')}</td><td>${esc(x.desc||'').slice(0,65)}</td><td>${pill(x.status)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No observations entered</td></tr>'}</tbody></table></div></div>
  <div class="card pad"><div class="classic-title"><b>Recent changes</b><span class="muted">Based on saved issue history</span></div>${recent.map(h=>`<div class="classic-event" data-dashissue="${esc(h.id)}"><b>${esc(h.id)}</b><span>${esc(h.action||h.status||'Updated')}</span><small>${esc((h.at||'').replace('T',' ').slice(0,16))}</small></div>`).join('')||'<p class="muted">No change history recorded</p>'}</div>
  <div class="card pad"><div class="classic-title"><b>Quick access</b><span class="muted">Existing sections — no changes to navigation</span></div><div class="classic-actions"><button class="btn" data-dashview="draw">${ic('map')}Drawings & Pins</button><button class="btn" data-dashview="plan">${ic('plan')}Planning & Progress</button><button class="btn" data-dashview="rep">${ic('rep')}Reports</button><button class="btn" data-dashview="set">${ic('set')}Settings</button></div><p class="muted">Progress and delay figures must use dated actual site updates. Blank activities are not assumed to be 0% complete.</p></div>
 </div>`;
}
function wireClassicDashboard(){
 const check=$('#dash-work-check');if(check)check.onclick=()=>{view='plan';planningPanel='schedule';render()};
 const route=(dest)=>{view=dest;pinMode=false;pickCtx=null;render()};
 document.querySelectorAll('[data-dashview]').forEach(el=>el.onclick=()=>route(el.dataset.dashview));
 document.querySelectorAll('[data-dashissue]').forEach(el=>el.onclick=()=>{const s=S.snags.find(x=>x.id===el.dataset.dashissue);if(s)issueDlg(s)});
 document.querySelectorAll('[data-dashdisc]').forEach(el=>el.onclick=()=>{F={st:'All',di:el.dataset.dashdisc,lo:'All',from:'',to:'',q:''};route('snags')});
 document.querySelectorAll('[data-dashfilter]').forEach(el=>el.onclick=()=>{const t=el.dataset.dashfilter;
 F={st:STAT.includes(t)?t:'All',di:'All',lo:'All',from:'',to:'',q:''};
 if(t==='aged'){F.q='';classicIssueSubset='aged'}else if(['unpinned','critical','due-soon','pending-verification'].includes(t))classicIssueSubset=t;else classicIssueSubset='all';route('snags')});
}
