 const init=()=>{if(LV.id===d.id&&LV.Z){v.Z=LV.Z;v.PX=LV.PX;v.PY=LV.PY;v.apply()}else v.fit()};img.complete?init():img.onload=init;
 const A=Annot({vp,stage,svg,W:d.w,H:d.h,v,img,key:d.id,marks:()=>d.marks,done:save,onSel:()=>paintRB(LH),onProps:()=>paintRB(LH),onClick:p=>placeAt(p,d),skip:e=>e.target.closest('.pin')&&T.tool==='pan'&&!pinMode&&!pickCtx});
