 document.body.appendChild(p);p.style.left=Math.max(8,Math.min(innerWidth-p.offsetWidth-8,r.right+12))+'px';p.style.top=Math.max(8,Math.min(innerHeight-p.offsetHeight-8,r.top-24))+'px';
