/* Non-destructive project integrity audit; data is never modified. */
let lastAudit=null;
async function validateProject(){
 const problems=[],items=S.snags||[],ids=new Set(),seqs=new Set(),draws=new Map((S.drawings||[]).map(d=>[d.id,d]));
 const imageRefs=new Set();
 for(const q of items){
  if(!q.id||ids.has(q.id))problems.push(`Missing or duplicate issue ID: ${q.id||'(blank)'}`);
  ids.add(q.id);
  if(q.seq!=null){if(seqs.has(q.seq))problems.push(`Duplicate serial number: ${q.seq}`);seqs.add(q.seq)}
  if(!q.desc||!q.desc.trim())problems.push(`${q.id}: missing description`);
  if(!DISC[q.disc])problems.push(`${q.id}: unsupported discipline`);
  if(!STAT.includes(q.status))problems.push(`${q.id}: unsupported status ${q.status}`);
  if(q.status==='Closed'&&!q.closedDate)problems.push(`${q.id}: closed without closing date`);
  if(q.drawingId){if(!draws.has(q.drawingId))problems.push(`${q.id}: missing linked drawing`);
   if(!Number.isFinite(+q.x)||!Number.isFinite(+q.y)||+q.x<0||+q.x>100||+q.y<0||+q.y>100)problems.push(`${q.id}: pin outside drawing`)}
  for(const ph of q.photos||[]){if(!ph.url)problems.push(`${q.id}: photo without URL`);else imageRefs.add(ph.url)}
 }
 for(const d of draws.values()){if(!d.url)problems.push(`${d.id}: drawing without image URL`);else imageRefs.add(d.url)}
 let okImages=0,badImages=0;
 for(const url of imageRefs){try{const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error(`HTTP ${r.status}`);const ct=r.headers.get('content-type')||'';if(!ct.startsWith('image/'))throw Error('not an image');okImages++}catch(e){badImages++;problems.push(`Image missing: ${url} (${e.message})`)}}
 let server=null;
 try{const r=await api('/api/health');if(!r.ok)throw Error(`HTTP ${r.status}`);server=await r.json();if(!server.state_valid)problems.push('Saved state contains invalid JSON');if(server.images_corrupt)problems.push(`${server.images_corrupt} corrupt images on disk`);const native=await api('/api/audit');if(!native.ok)throw Error('Disk audit HTTP '+native.status);const disk=await native.json();server.projectAudit=disk;if(!disk.passed)for(const problem of disk.problems||[])problems.push('Disk: '+problem)}catch(e){problems.push('Server health check failed: '+e.message)}
 const scheduleTasks=(sched?.rows||[]).filter(r=>r.type==='Task').length;
 if(!scheduleTasks)problems.push('No contractor schedule tasks loaded');
 lastAudit={at:new Date().toISOString(),demo:!!S.settings.demo,issues:items.length,linkedPins:items.filter(x=>x.drawingId&&x.x!=null).length,drawings:draws.size,imagesChecked:imageRefs.size,imagesOK:okImages,imagesMissing:badImages,scheduleActivities:scheduleTasks,server,problems,passed:problems.length===0};
 const el=$('#auditresult');if(el)el.innerHTML=`<div style="color:${lastAudit.passed?'#208a56':'#b85e24'};font-weight:700">${lastAudit.passed?'✓ Validation passed':'⚠ '+problems.length+' validation issue(s)'}</div><div>Issues: ${items.length} | Pins: ${lastAudit.linkedPins} | Photos/drawings checked: ${okImages}/${imageRefs.size} | Schedule activities: ${scheduleTasks}</div>${problems.length?'<ul>'+problems.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':''}<small>Non-destructive check · ${esc(lastAudit.at)}</small>`;
 return lastAudit;
}
