// A failed headless PDF conversion must not download an HTML error page as .pdf.
async function downloadServerPDF(url,name){
 const response=await fetch(url,{cache:'no-store'});
 if(!response.ok)throw Error((await response.text()).slice(0,200));
 const blob=await response.blob();
 const signature=await blob.slice(0,5).text();
 if(signature!=='%PDF-')throw Error('Invalid PDF response');
 const objectUrl=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=objectUrl;a.download=name;document.body.appendChild(a);a.click();a.remove();
 setTimeout(()=>URL.revokeObjectURL(objectUrl),3000);
}
