function layoutNode(){const r=document.createElement('div'),d=curD();r.className='pr';if(!d)return r;const L=flt().filter(x=>x.drawingId===d.id&&x.x!=null),u=Math.max(d.w,d.h)/900;
 r.innerHTML=`<h3 style="margin:0 0 6px">${esc(d.name)} — GEM Layout &amp; Pins</h3><div class="pmap" style="position:relative;width:100%;aspect-ratio:${d.w}/${d.h}"><img src="${esc(d.url)}" style="width:100%;height:100%;display:block"><svg viewBox="0 0 ${d.w} ${d.h}" style="position:absolute;left:0;top:0;width:100%;height:100%">${(d.marks||[]).map(m=>markSVG(m,u)).join('')}</svg>${L.map(x=>`<div class="pin" style="left:${x.x}%;top:${x.y}%">${pinSVG(x.disc)}</div>`).join('')}</div><div class="plegend">${legend()}</div>`;return r}
function printNode(modalOnly){const r=document.createElement('div');r.className='pr';
 if(modalOnly){const src=$('#modal .dlg');syncForm(src);const c=src.cloneNode(true);c.querySelectorAll('.foot,.x,[data-an],#addph,#locb,#unloc').forEach(e=>e.remove());c.classList.add('pr-dlg');r.appendChild(c);return r}
 if(view==='draw')return layoutNode();
 const main=$('main');syncForm(main);const c=main.cloneNode(true);c.querySelectorAll('.noprint,.bar button,#fs,#fd,#fq,.focused-sidebar,.focused-heading button').forEach(e=>e.remove());c.querySelectorAll('#plscroll,.sch-table,.sch-gantt-scroll,.focused-content').forEach(el=>{el.style.overflow='visible';el.style.maxHeight='none';el.style.minHeight='0';el.style.height='auto'});c.className='pr-main';r.appendChild(c);r.dataset.natw=main.scrollWidth;return r}
function composeSheet(P,modalOnly){const sh=document.createElement('div');sh.className='psheet';let head=null,foot=null;
 if(P.head&&!modalOnly){head=$('.head').cloneNode(true);head.classList.add('pr-head');sh.appendChild(head)}
 const clip=document.createElement('div'),body=document.createElement('div'),node=printNode(modalOnly);clip.className='pclip';body.className='pbody';body.appendChild(node);clip.appendChild(body);sh.appendChild(clip);
 if(P.foot){foot=document.createElement('div');foot.className='pfoot';foot.textContent=`${S.settings.company}${S.settings.admin?' · '+S.settings.admin:''} · Printed ${new Date().toLocaleString('en-GB')}`;sh.appendChild(foot)}
 return{sh,head,clip,body,foot,natw:+node.dataset.natw||0,isMap:!modalOnly&&view==='draw'}}
function layoutSheet(c,P,dm){const aw=dm.aw;c.sh.style.width=aw+'px';
 const ah=Math.floor(dm.H-2*dm.mp-(c.head?c.head.offsetHeight+8:0)-(c.foot?c.foot.offsetHeight+8:0)-6),natW=Math.max(aw,c.natw||0);let z=1;
 const fitH=()=>{for(let i=0;i<6;i++){c.body.style.zoom=1;c.body.style.width=(aw/z)+'px';const h=c.body.offsetHeight||1,nz=Math.min(z,ah/h);if(Math.abs(nz-z)<.004)break;z=nz}};
 if(c.isMap&&P.scale!=='none'&&P.scale!=='pct'){const d=curD(),pm=c.body.querySelector('.pmap');if(d&&pm){const ex=c.body.querySelector('h3').offsetHeight+12+c.body.querySelector('.plegend').offsetHeight+8,wmax=Math.max(120,(ah-ex)*d.w/d.h);pm.style.width=Math.min(aw,wmax)+'px';pm.style.margin='0 auto'}c.body.style.zoom=1;c.body.style.width=aw+'px';return{z:1,ah,pages:1}}
 if(P.scale==='pct')z=Math.max(.1,(+P.pct||100)/100);
 else if(P.scale==='fitp'||(c.isMap&&P.scale==='fitw')){z=Math.min(1,aw/natW);fitH()}
 else if(P.scale==='fitw')z=Math.min(1,aw/natW);
 c.body.style.zoom=z;c.body.style.width=(aw/z)+'px';const vh=c.body.offsetHeight*z;return{z,ah,pages:Math.max(1,Math.ceil(vh/ah-.02))}}
/* ================= Classic UX: simplify without removing features ================= */
let classicAdvancedFiltersOpen=false;
function simplifyClassicWorkspace(){
 const main=document.querySelector('main');if(!main)return;
 // Consistent page bars, same Classic color scheme and existing click handlers.
 main.querySelectorAll('.bar').forEach(x=>x.classList.add('classic-pagebar'));
 const makeTools=(title,items)=>{
  if(!items.length)return null;
  const outer=document.createElement('details');outer.className='classic-more-tools noprint';
  const label=document.createElement('summary');label.textContent=title;outer.appendChild(label);
  const tray=document.createElement('div');tray.className='classic-tools-tray';
  for(const item of items)tray.appendChild(item);outer.appendChild(tray);return outer;
 };
 if(view==='snags'){
  // Preserve native event handlers by moving, not rebuilding, the buttons.
  const bar=main.querySelector('.bar');if(bar){
   const extra=[...bar.children].filter(x=>['importcsv','importxlsx','exportxlsx','exportissues'].includes(x.dataset?.a)||x.id==='import_mobile_field'||x.matches?.('a[href="android_field.html"]'));
   const drawer=makeTools('Data & Exchange / استيراد وتصدير',extra);
   if(drawer)bar.appendChild(drawer);
  }
  const filters=main.querySelector('.card.pad.bar.noprint');
  if(filters){
   const extras=[...filters.children].filter(x=>['fpriority','fdue','ffrom','fto'].includes(x.id)||x.querySelector?.('#ffrom,#fto'));
   const drawer=makeTools('Advanced filters / فلاتر متقدمة',extras);
   if(drawer){drawer.open=classicAdvancedFiltersOpen;drawer.addEventListener('toggle',()=>{classicAdvancedFiltersOpen=drawer.open});filters.appendChild(drawer)}
   filters.classList.add('classic-filterbar');
  }
 }
 if(view==='rep'){
  const bar=main.querySelector('.focused-content > .bar');
  if(bar){
   const extras=[...bar.querySelectorAll('button[data-a]')].filter(x=>['csv','word','photoword','xls','pdf'].includes(x.dataset.a));
   const drawer=makeTools('Export / تنزيل التقرير',extras);
   if(drawer)bar.appendChild(drawer);
  }
 }
 // Dialogs keep all original behavior but align headings, footer actions and focus.
 const dlg=document.querySelector('#modal .dlg');
 if(dlg){dlg.setAttribute('role','dialog');dlg.setAttribute('aria-modal','true')}
 main.querySelectorAll('.classic-back').forEach(b=>b.title='Return to main list / الرجوع للقائمة الرئيسية');
}
function printDlg(modalOnly){const P={...PDEF,...S.settings.print,...(view==='rep'?S.settings.reportPrint?.[reportsPanel]:{})},m=$('#modal2');m.hidden=false;m.dataset.keep='1';let page=1,pages=1,previewZoom=1;
 const sel=(id,l,o)=>`<label class="pl">${l}</label><select id="p_${id}">${o.map(([v,t])=>`<option value="${v}" ${String(P[id])===v?'selected':''}>${t}</option>`).join('')}</select>`;
 m.innerHTML=`<div class="pd"><div class="pset"><h2>${ic('print')} Print</h2><button class="btn pri bigp" id="pgo">${ic('print')}<span>Print</span></button><p class="muted sm">The Windows print window opens next — choose the <b>printer</b>, <b>copies</b> and <b>page range</b> there.</p><h3>Settings</h3><p class="muted">Your print choices are saved for this report. Export to PDF via the Windows printer dialog if direct PDF is unavailable.</p><label class="pl">Preview / معاينة الصفحات</label><select id="p_preview"><option value="all">كل الصفحات متتالية / All pages scrolling</option><option value="one">صفحة واحدة / Single page</option></select><label class="pl">Print selection / نطاق الطباعة</label><select id="p_scope"><option value="all">All pages / طباعة الكل</option><option value="current">Current page / الصفحة الحالية</option><option value="range">Page range / صفحات محددة</option></select><input type="text" id="p_range" placeholder="مثال: 1,3-5" style="display:none" aria-label="Pages to print"><div class="pl0">${modalOnly?'Print: this issue sheet':'Print: '+(view==='draw'?'the layout with pins &amp; markup':'the current page')}</div>
 ${sel('orient','Orientation',[['portrait','Portrait Orientation'],['landscape','Landscape Orientation']])}${sel('paper','Paper size',[['A4','A4 — 21 × 29.7 cm'],['A3','A3 — 29.7 × 42 cm'],['Letter','Letter'],['Legal','Legal']])}
 ${sel('margin','Margins',[['normal','Normal Margins'],['narrow','Narrow Margins'],['wide','Wide Margins']])}${sel('scale','Scaling',[['none','No Scaling'],['fitw','Fit All Columns on One Page'],['fitp','Fit Sheet on One Page'],['pct','Custom Scale %']])}
 <label class="pl">Custom scale %</label><input type="number" id="p_pct" min="10" max="400" value="${P.pct}">${sel('color','Colour',[['color','Colour'],['bw','Black &amp; White']])}
 <label class="pl chk"><input type="checkbox" id="p_head" ${P.head?'checked':''}> Header (logos &amp; title)</label><label class="pl chk"><input type="checkbox" id="p_foot" ${P.foot?'checked':''}> Footer (name &amp; date)</label></div>
 <div class="pprev"><div class="pnav"><button class="btn" id="pp">‹</button><span id="pn"></span><button class="btn" id="pnx">›</button><span style="flex:1"></span><button class="btn" id="pzoomout" title="Zoom out">−</button><span id="pzoomlabel">100%</span><button class="btn" id="pzoomin" title="Zoom in">+</button><button class="btn" id="pc">${ic('close')}Close</button></div><div class="pstage" id="pstage"></div></div></div>`;
 const close=()=>{m.hidden=true;m.dataset.keep='0';m.innerHTML=''},g=id=>$('#p_'+id);
 const read=()=>{P.orient=g('orient').value;P.paper=g('paper').value;P.margin=g('margin').value;P.scale=g('scale').value;P.pct=+g('pct').value||100;P.color=g('color').value;P.head=g('head').checked;P.foot=g('foot').checked;if(view==='rep'){S.settings.reportPrint=S.settings.reportPrint||{};S.settings.reportPrint[reportsPanel]={...P}}else S.settings.print={...P}};
 const prev=()=>{const dm=dims(P),box=$('#pstage');if(!box)return;box.innerHTML='';const c=composeSheet(P,modalOnly),pg=document.createElement('div');pg.className='pg'+(P.color==='bw'?' bw':'');pg.style.cssText=`width:${dm.W}px;height:${dm.H}px;padding:${dm.mp}px;transform-origin:0 0`;pg.appendChild(c.sh);box.appendChild(pg);
 const info=layoutSheet(c,P,dm);pg.remove();pages=info.pages;page=Math.min(page,pages);const k=Math.max(.12,Math.min(1.8,Math.min((box.clientWidth-45)/dm.W,.72)*previewZoom));
 const makePage=(n)=>{const sheet=pg.cloneNode(true),clip=sheet.querySelector('.pclip'),body=sheet.querySelector('.pbody');clip.style.height=info.ah+'px';clip.style.overflow='hidden';body.style.marginTop=(-(n-1)*info.ah/info.z)+'px';sheet.style.transform=`scale(${k})`;const w=document.createElement('div');w.className='pgbox';w.style.width=dm.W*k+'px';w.style.height=dm.H*k+'px';w.appendChild(sheet);return w};
 const showAll=$('#p_preview')?.value!=='one';$('#pzoomlabel').textContent=Math.round(previewZoom*100)+'%';box.classList.toggle('preview-all',showAll);const previewScope=$('#p_scope')?.value||'all',selected=previewScope==='range'?selectedPrintPages({printScope:'range',printRange:$('#p_range').value},pages):previewScope==='current'?[page]:Array.from({length:pages},(_,i)=>i+1);if(showAll){for(const n of selected.slice(0,150))box.appendChild(makePage(n))}else box.appendChild(makePage(previewScope==='range'?(selected.includes(page)?page:selected[0]):page));$('#pn').textContent=`${showAll?selected.length+' selected · ':''}Page ${page} of ${pages} · ${Math.round(info.z*100)}%`;$('#pp').disabled=showAll||page<=1;$('#pnx').disabled=showAll||page>=pages};
 m.querySelectorAll('.pset select,.pset input').forEach(e=>e.onchange=()=>{read();save();page=1;prev()});
 $('#p_preview').onchange=prev;$('#p_scope').onchange=()=>{const scope=$('#p_scope').value;$('#p_range').style.display=scope==='range'?'block':'none';if(scope==='current')$('#p_preview').value='one';else $('#p_preview').value='all';prev()};$('#p_range').oninput=prev;$('#pp').onclick=()=>{if(page>1){page--;prev()}};$('#pnx').onclick=()=>{if(page<pages){page++;prev()}};$('#pc').onclick=close;$('#pzoomin').onclick=()=>{previewZoom=Math.min(3,+(previewZoom*1.25).toFixed(2));prev()};$('#pzoomout').onclick=()=>{previewZoom=Math.max(.35,+(previewZoom/1.25).toFixed(2));prev()};
 $('#pgo').onclick=()=>{read();save();P.printScope=$('#p_scope').value;P.printRange=$('#p_range').value.trim();P.currentPage=page;close();setTimeout(()=>doPrint({...P},modalOnly),120)};requestAnimationFrame(prev)}
function selectedPrintPages(P,total){
 if(P.printScope==='current')return [Math.max(1,Math.min(total,P.currentPage||1))];
 if(P.printScope==='range'){
  const set=new Set();for(const part of String(P.printRange||'').split(',')){const match=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!match)continue;const a=+match[1],b=+(match[2]||match[1]);for(let i=Math.max(1,Math.min(a,b));i<=Math.min(total,Math.max(a,b));i++)set.add(i)}
  if(!set.size){toast('Invalid page range — printing all pages');return Array.from({length:total},(_,i)=>i+1)}return [...set].sort((a,b)=>a-b)
 }
 return Array.from({length:total},(_,i)=>i+1)
}
function doPrint(P,modalOnly){const dm=dims(P),c=composeSheet(P,modalOnly),pr=$('#printroot');pr.innerHTML='';pr.className='measure'+(P.color==='bw'?' bw':'');pr.appendChild(c.sh);const info=layoutSheet(c,P,dm),pages=selectedPrintPages(P,Math.min(250,info.pages));
 const base=c.sh.cloneNode(true);pr.innerHTML='';for(const n of pages){const page=base.cloneNode(true),clip=page.querySelector('.pclip'),body=page.querySelector('.pbody');clip.style.height=info.ah+'px';clip.style.overflow='hidden';body.style.marginTop=(-(n-1)*info.ah/info.z)+'px';page.classList.add('print-paper');pr.appendChild(page)}
 pr.className=P.color==='bw'?'bw':'';
 const st=document.createElement('style');st.id='pst';st.textContent=`@page{size:${P.paper} ${P.orient};margin:${dm.mm}mm}.print-paper{break-after:page;page-break-after:always;overflow:hidden;width:${dm.aw}px;max-height:${dm.H-2*dm.mp}px}.print-paper:last-child{break-after:auto;page-break-after:auto}`;document.head.appendChild(st);
 let fin=false;const done=()=>{if(fin)return;fin=true;pr.innerHTML='';st.remove();window.removeEventListener('afterprint',done);window.removeEventListener('focus',onFocus)};const onFocus=()=>setTimeout(done,1200);window.addEventListener('afterprint',done,{once:true});window.addEventListener('focus',onFocus,{once:true});try{window.print()}catch(e){done();toast('Print error: '+e.message)}setTimeout(done,30000)}

